using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieve a specific configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'MaxRetries', 'Timeout')")] string key)
    {
        var config = AppConfig.Current;

        return key switch
        {
            "MaxRetries" => config.MaxRetries.ToString(),
            "Timeout" => config.TimeoutSeconds.ToString(),
            "Environment" => config.Environment,
            "FeatureFlags" => string.Join(", ", config.FeatureFlags),
            _ => $"Unknown key: {key}. Valid keys: MaxRetries, Timeout, Environment, FeatureFlags"
        };
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(AppConfig.Current, AppConfig.SerializerOptions);

    [McpServerResource(
        UriTemplate = "config://features",
        Name = "Feature Flags",
        MimeType = "application/json"),
     Description("Returns the current feature flags.")]
    public static string GetFeatureFlags() =>
        JsonSerializer.Serialize(AppConfig.Current.FeatureFlags, AppConfig.SerializerOptions);
}

using System.Text.Json;

public record AppConfig(
    string Environment,
    int MaxRetries,
    int TimeoutSeconds,
    string[] FeatureFlags)
{
    public static AppConfig Current { get; } = new(
        Environment: "Production",
        MaxRetries: 3,
        TimeoutSeconds: 30,
        FeatureFlags: ["dark-mode", "beta-search", "new-dashboard"]);

    public static JsonSerializerOptions SerializerOptions { get; } = new()
    {
        WriteIndented = true
    };
}

